    expectedAnswer: "A senior machine-coding assessment should demonstrate a clean API, explicit state invariants, edge-case handling, and predictable complexity. A representative implementation is an LRU cache.",
    deepExplanation: "Step 1 — Understand the final-assessment requirement.\n\nStep 1 — Map gives lookup; a doubly linked list gives O(1) recency updates.\n\nWITHOUT BUILT-IN / CORE:\n```ts\nclass LruNode<K, V> {\n  constructor(\n    public key: K,\n    public value: V,\n    public prev: LruNode<K, V> | null = null,\n    public next: LruNode<K, V> | null = null,\n  ) {}\n}\n\nclass LRUCache<K, V> {\n  private readonly map = new Map<K, LruNode<K, V>>();\n  private readonly head = new LruNode<K, V>(\n    undefined as K,\n    undefined as V,\n  );\n  private readonly tail = new LruNode<K, V>(\n    undefined as K,\n    undefined as V,\n  );\n\n  constructor(private readonly capacity: number) {\n    this.head.next = this.tail;\n    this.tail.prev = this.head;\n  }\n\n  get(key: K): V | undefined {\n    const node = this.map.get(key);\n    if (!node) return undefined;\n\n    this.remove(node);\n    this.insertAfterHead(node);\n    return node.value;\n  }\n\n  set(key: K, value: V): void {\n    if (this.capacity <= 0) return;\n\n    const existing = this.map.get(key);\n\n    if (existing) {\n      existing.value = value;\n      this.remove(existing);\n      this.insertAfterHead(existing);\n      return;\n    }\n\n    const node = new LruNode(key, value);\n    this.map.set(key, node);\n    this.insertAfterHead(node);\n\n    if (this.map.size > this.capacity) {\n      const oldest = this.tail.prev;\n\n      if (oldest && oldest !== this.head) {\n        this.remove(oldest);\n        this.map.delete(oldest.key);\n      }\n    }\n  }\n\n  private remove(node: LruNode<K, V>): void {\n    node.prev!.next = node.next;\n    node.next!.prev = node.prev;\n  }\n\n  private insertAfterHead(node: LruNode<K, V>): void {\n    node.next = this.head.next;\n    node.prev = this.head;\n    this.head.next!.prev = node;\n    this.head.next = node;\n  }\n}\n```\n\nWITH BUILT-IN:\n```ts\nfunction createMapLru<K, V>(capacity: number) {\n  const cache = new Map<K, V>();\n\n  return {\n    get(key: K): V | undefined {\n      const value = cache.get(key);\n      if (value === undefined) return undefined;\n\n      cache.delete(key);\n      cache.set(key, value);\n      return value;\n    },\n\n    set(key: K, value: V): void {\n      cache.delete(key);\n      cache.set(key, value);\n\n      while (cache.size > capacity) {\n        const oldest = cache.keys().next().value as K | undefined;\n        if (oldest === undefined) break;\n        cache.delete(oldest);\n      }\n    },\n  };\n}\n```\n\nExample:\ncapacity=2; A, B; get(A); set(C) → B is evicted.\n\nComplexity:\nO(1) average get/set/eviction; O(capacity) memory.\n\nStep 5 — Senior interview takeaway:\nExplain correctness, complexity, edge cases, and production trade-offs before implementation.",
